def main():
    manifest = json.loads((OUT / 'approved-manifest.json').read_text())
    refs = {c['id']: c for c in manifest['cards']}
    cards = []
    for cid, category, title, summary, clinical, badges in COPY:
        sources = ['zzs-trauma', 'erc-first-aid-2025'] if category == 'trauma' else ['erc-bls-2025', 'zzs-cpr']
        sources += {'C01':['criminal-code'], 'C02':['zzs-call','eu-112'], 'C07':['erc-position-2025','zzs-unconscious'], 'C08':['zzs-bleeding'], 'C11':['helmet-review-pending'], 'C15':['extrication-review-pending']}.get(cid, [])
        cards.append(dict(id=cid, category=category, title=title, summary=summary, clinical=clinical,
            badges=badges, questionIds=refs[cid]['questionIds'], image=f'first_aid/graphics/{cid}.webp',
            clinicalReview='PENDING_INDEPENDENT_REVIEW', translationReview='DRAFT_REVIEW_REQUIRED',
            sourceIds=sources, relatedCards={'C03':['C04','C05'], 'C04':['C03','C05'], 'C07':['C03','C05'], 'C13':['C08','C12'], 'C15':['C14','C05'], 'C16':['C05','C06']}.get(cid, [])))
    (OUT / 'cards.json').write_text(json.dumps(dict(schemaVersion=1, clinicalReview='PENDING_INDEPENDENT_REVIEW',
        publicationReady=False, cards=cards), ensure_ascii=False, indent=2)+'\n')

if __name__ == '__main__':
    main()
